from collections import defaultdict, Counter, deque

def comps(g,bg):
 h,w=len(g),len(g[0]); seen=set(); objs=[]
 for r in range(h):
  for c in range(w):
   col=g[r][c]
   if col==bg or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    y,x=q.pop(); cells.append((y,x))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     pt=(y+dy,x+dx)
     if 0<=pt[0]<h and 0<=pt[1]<w and pt not in seen and g[pt[0]][pt[1]]==col:
      seen.add(pt);q.append(pt)
   y0=min(y for y,x in cells);x0=min(x for y,x in cells)
   sh=frozenset((y-y0,x-x0) for y,x in cells)
   objs.append((col,len(cells),(y0,x0,max(y for y,x in cells),max(x for y,x in cells)),sh,cells))
 return objs
